function createGreeting(greeting) {
  return function(name) {
    return greeting + ", " + name + "!";
  };
}

let sayHello = createGreeting("Hello");
let sayHi = createGreeting("Hi");

console.log(sayHello("Alex"));  // "Hello, Alex!"
console.log(sayHi("Sam"));      // "Hi, Sam!"

// sayHello still has access to 'greeting' even though
// createGreeting() has already finished executing!

function createAccount(initialBalance) {
  let balance = initialBalance;  // private!

  return {
    deposit(amount) {
      if (amount > 0) balance += amount;
      return balance;
    },
    withdraw(amount) {
      if (amount > 0 && amount <= balance) balance -= amount;
      return balance;
    },
    getBalance() {
      return balance;
    }
  };
}

let account = createAccount(100);
console.log(account.getBalance());  // 100
account.deposit(50);
console.log(account.getBalance());  // 150
// account.balance → undefined (can't access directly!)

// Factory function with private state
function createLogger(prefix) {
  let count = 0;
  return function(message) {
    count++;
    console.log(`[${prefix} #${count}] ${message}`);
  };
}

let appLog = createLogger("APP");
let errLog = createLogger("ERR");
appLog("started");    // [APP #1] started
errLog("failed");     // [ERR #1] failed
appLog("running");    // [APP #2] running

// Memoization with closure
function memoize(fn) {
  let cache = {};
  return function(...args) {
    let key = JSON.stringify(args);
    if (cache[key] !== undefined) return cache[key];
    cache[key] = fn(...args);
    return cache[key];
  };
}

let slowSquare = memoize(n => n * n);
console.log(slowSquare(5));  // 25 (computed)
console.log(slowSquare(5));  // 25 (cached!)
